from pathlib import Path
import json,re,html,base64,hashlib,shutil,math
E=lambda x:html.escape(str(x or ''),quote=True)
def num(n,forms=('курс','курса','курсов')):
 return forms[0] if n%10==1 and n%100!=11 else forms[1] if 2<=n%10<=4 and not 12<=n%100<=14 else forms[2]
def purl(slug=''):return '/kursy/'+(slug.strip('/')+'/' if slug else '')
def save(path,s):
 p=OUT/path.lstrip('/');p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
def readasset(path):
 p=OUT/path
 if not p.exists():return None
 mime='image/webp' if p.suffix=='.webp' else 'image/png'
 return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()
def ill(slug):
 if (OUT/f'assets/illustrations/{slug}.webp').exists():return f'assets/illustrations/{slug}.webp'
 if (OUT/f'assets/illustrations/{slug}.png').exists():return f'assets/illustrations/{slug}.png'
 return None
def make_direction_image(slug):
 b=B[slug];image=readasset(ill(slug)) if ill(slug) else None
 if not image:return
 lines=b['cardLines'];maxlen=max(map(len,lines));size=min(83,850/(maxlen*.56));start=645 if len(lines)<3 else 565
 text=''.join(f'<text x="54" y="{start+i*93}" font-family="Manrope,Arial,sans-serif" font-size="{size:.1f}" font-weight="800" letter-spacing="-2.5" fill="#24231f">{E(line)}</text>' for i,line in enumerate(lines))
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1000" height="820" viewBox="0 0 1000 820"><defs><clipPath id="round"><rect width="1000" height="820" rx="54"/></clipPath><linearGradient id="fade" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#fac092" stop-opacity="0"/><stop offset="1" stop-color="{b['color']}"/></linearGradient></defs><g clip-path="url(#round)"><rect width="1000" height="820" fill="{b['color']}"/><image href="{image}" x="0" y="-125" width="1000" height="780" preserveAspectRatio="xMidYMid slice"/><rect y="405" width="1000" height="145" fill="url(#fade)"/><rect y="550" width="1000" height="270" fill="{b['color']}"/>{text}<circle cx="914" cy="71" r="35" fill="#fff9f0" fill-opacity=".86"/><path d="M902 83l23-24m-21 0h21v21" stroke="#33372b" stroke-width="3" fill="none"/></g></svg>'''
 save(f'assets/direction-cards/{slug}.svg',svg)
def landing_visual(l):
 if not l['slug']:return '/kursy/assets/hero.png'
 path='assets/landing-heroes/'+l['slug'].replace('/','--')+'.svg'
 if l['kind']=='category':slug=l['slug']; return '/kursy/'+ill(slug) if ill(slug) else '/kursy/assets/hero.png'
 if l['kind'] in ['school','school-programme']:
  groups={}
  for id in l['courseIds']:
   c=COURSES[id];k=c['primaryCategory'];groups[k]=groups.get(k,0)+1
  chosen=[k for k,n in sorted(groups.items(),key=lambda x:-x[1]) if ill(k)][:3]
  images=''.join(f'<image href="{readasset(ill(k))}" x="{70+i*220}" y="{50+(i%2)*150}" width="390" height="390" clip-path="url(#c{i})"/>' for i,k in enumerate(chosen))
  clips=''.join(f'<clipPath id="c{i}"><rect x="{70+i*220}" y="{50+(i%2)*150}" width="390" height="390" rx="110"/></clipPath>' for i in range(len(chosen)))
  label=l['label'];fs=min(92,780/max(1,len(label))/.56)
  svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="850" viewBox="0 0 1000 850"><defs>{clips}</defs><rect width="1000" height="850" rx="48" fill="#f3dcc1"/>{images}<rect x="65" y="644" width="870" height="136" rx="32" fill="#fff8eb"/><text x="105" y="735" font-family="Arial,sans-serif" font-weight="800" font-size="{fs}" fill="#27271f">{E(label)}</text></svg>'
 else:
  exam=l['parent'];topic=l['slug'].split('/')[-1];subject=readasset(ill(topic)) if ill(topic) else readasset(ill(exam))
  examart=readasset(ill(exam));label=l.get('label','').replace('ЕГЭ','').replace('ОГЭ','').strip(' ·—:')
  svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="850" viewBox="0 0 1000 850"><defs><clipPath id="a"><rect x="80" y="65" width="650" height="650" rx="130"/></clipPath><clipPath id="b"><circle cx="760" cy="580" r="180"/></clipPath></defs><rect width="1000" height="850" rx="48" fill="#e8eadb"/><image href="{subject}" x="80" y="65" width="650" height="650" clip-path="url(#a)"/><image href="{examart}" x="580" y="400" width="360" height="360" clip-path="url(#b)"/><rect x="45" y="610" width="330" height="130" rx="28" fill="#fff8ec" transform="rotate(-7 200 680)"/><text x="87" y="705" font-family="Arial,sans-serif" font-weight="800" font-size="86" fill="#26271f" transform="rotate(-7 200 680)">{exam.upper()}</text></svg>'
 save(path,svg);return '/kursy/'+path
def document(title,description,path,body,page='catalog',image='/kursy/assets/hero.png',extra=''):
 canonical='https://pro-schools.ru'+path
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow"><title>{E(title)}</title><meta name="description" content="{E(description)}"><link rel="canonical" href="{E(canonical)}"><meta property="og:type" content="website"><meta property="og:locale" content="ru_RU"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(description)}"><meta property="og:url" content="{E(canonical)}"><meta property="og:image" content="{E(ORIGIN+image)}"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/kursy/assets/fonts.css"><link rel="stylesheet" href="/kursy/assets/style.css"><link rel="stylesheet" href="/kursy/assets/compact.css"><script src="/kursy/assets/catalog-data.js" defer></script><script src="/kursy/assets/catalog-v2.js" defer></script><script src="/kursy/assets/select-controls.js" defer></script>{extra}</head><body data-page="{page}" data-path="{E(path)}"><a class="skip" href="#main">К содержимому</a>{HEADER}{body}{FOOTER}</body></html>'''
def card(c):
 category=CATS[c['primaryCategory']]['label'];cover='/kursy/assets/course-thumbnails/'+c['id']+'.svg';desc=' · '.join(c['topics'][:2]);age=c['age'];price=c['price'];unknown=c['priceValue'] is None
 return f'''<article class="course-card" data-course="{c['id']}" data-min="{c['min'] or ''}" data-max="{c['max'] or ''}" data-grade-min="{c['gradeMin'] or ''}" data-grade-max="{c['gradeMax'] or ''}" data-price="{c['priceValue'] if not unknown else ''}" data-unit="{E(c['unitKey'])}" data-online="{int(c['online'])}" data-trial="{int(c['trial'])}" data-discount="{int(c['discount'])}" data-grades="{E(chr(44).join(str(n) for n in c.get('grades',[])))}" data-brand="{c['brandSlug']}" data-search="{E(c['fullTitle']+' '+c['brand']+' '+desc)}"><div class="card-art"><a href="{c['path']}" aria-label="{E(c['fullTitle'])}"><img src="{cover}" alt="{E(c['fullTitle'])}" width="800" height="480" loading="lazy"></a></div><button class="favorite" data-favorite="{c['id']}" aria-label="Добавить в избранное" aria-pressed="false">♡</button><div class="card-body"><a class="school-name" href="/kursy/shkoly/{c['brandSlug']}/"><span class="school-mark">{E(c['brand'][0])}</span>{E(c['brand'])}</a><h3><a href="{c['path']}">{E(c['fullTitle'])}</a></h3><p class="course-desc">{E(desc or category)}</p><div class="card-meta"><span>{E(age)}</span><span>{E(c['format'])}</span></div><div class="card-price"><div><strong>{E(price)}</strong><small>{E('Уточняется при записи' if unknown else c['unit'])}</small></div><a class="card-arrow" href="{c['path']}" aria-label="Подробнее: {E(c['fullTitle'])}">↗</a></div></div><div class="compare-control"><label><input type="checkbox" data-compare="{c['id']}">Сравнить</label>{'<span class="trial-label">Первый урок бесплатно</span>' if c['trial'] else '<span>'+E(category)+'</span>'}</div></article>'''
def directions(slugs,all=False):
 return '<div class="direction-grid illustrated-directions"'+(' id="all-directions"' if all else '')+'>'+''.join(f'<a class="direction-card" href="{purl(s)}"><img src="/kursy/assets/direction-cards/{s}.svg" alt="{E(B[s]["title"])}" width="1000" height="820" loading="lazy"><span class="direction-count">{CATS[s]["count"]} {num(CATS[s]["count"])}</span></a>' for s in slugs)+'</div>'
def crumbs(l):
 parts=['<a href="https://pro-schools.ru/">Главная</a>','<a href="/kursy/">Курсы для детей</a>']
 if l.get('parent'):parts.append(f'<a href="{purl(l["parent"])}">{E(LANDINGS.get(l["parent"],CATS.get(l["parent"],{})).get("label","Курсы"))}</a>')
 if l['slug']:parts.append(E(l.get('label',l['h1'])))
 return '<div class="breadcrumbs">'+'<span>/</span>'.join(parts)+'</div>'
def hero(l):
 if not l['slug']:
  return f'''<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> МАЛЕНЬКИЙ ШАГ. БОЛЬШОЕ БУДУЩЕЕ.</div><h1>Большие открытия<br>начинаются<br>с <span class="underline">«мне интересно»</span></h1><p>Курсы, в которые хочется включиться.<br>Найдите то самое увлечение для своего ребёнка.</p><div class="hero-actions"><a href="#catalog" class="button dark">Найти свой курс <span>↗</span></a><button class="text-button" data-quiz>Помогите с выбором →</button></div><div class="hero-foot"><span class="mini-star">✳</span><span>{len(D['courses'])} программ · {len(D['brands'])} {num(len(D['brands']),('школа','школы','школ'))}<br>Все детские увлечения в одном месте</span></div></div><div class="hero-art"><img src="/kursy/assets/hero.png" alt="Книга, планета, карандаш и геймпад — мир детских увлечений" fetchpriority="high"><span class="art-note note-one">А что, если я создам свою игру?</span><span class="art-note note-two">Начнём с интереса <i>✦</i></span></div></section>'''
 b=B.get(l['slug']);h=b['heroTitle'] if b else l['h1'];intro=b['heroDescription'] if b else l['intro'];kick=b['kicker'] if b else ('ПОДГОТОВКА К '+l['parent'].upper() if l['kind']=='exam-subject' else 'ПРОГРАММЫ '+l.get('label','').upper());image=landing_visual(l)
 return f'''<section class="hero category-hero {l['kind']}-hero" style="--category-color:{b['color'] if b else '#e7ecdf'}"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span>{E(kick)}</div><p class="category-name">{E(l.get('label',l['h1']))} / {l['count']} {num(l['count'])}</p><h1>{'<br>'.join(E(h).split(chr(10)))}</h1><p>{E(intro)}</p><div class="hero-actions"><a href="#catalog" class="button dark">Выбрать курс <span>↗</span></a><a href="/kursy/" class="text-button">Все направления →</a></div></div><div class="hero-art"><img src="{image}" alt="{E(l.get('label',l['h1']))} — тематическая иллюстрация" fetchpriority="high"><span class="art-note note-two">С интересом к новому <i>✦</i></span></div></section>'''
def filters(l):
 current=l['slug'] if l['kind']=='category' else l.get('parent','')
 options='<option value="/kursy/">Все направления</option><option value="/kursy/shkolnaya-programma/">Школьная программа</option>'+''.join(f'<option value="{purl(c["slug"])}" {"selected" if current==c["slug"] else ""}>{E(c["label"])}</option>' for c in D['categories'])
 brandoptions='<option value="">Все школы</option>'+''.join(f'<option value="{b["id"]}" {"selected" if l.get("brandSlug")==b["id"] else ""}>{E(b["name"])}</option>' for b in D['brands'])
 return f'''<aside class="filters" id="filters"><div class="filter-heading"><strong>Подобрать курс</strong><button id="reset" class="reset">Сбросить</button><button class="mobile-filter-close icon-button" aria-label="Закрыть фильтры">×</button></div><div class="field"><label for="category">Направление</label><select id="category" data-navigate>{options}</select></div><div class="field"><label for="age">Возраст ребёнка</label><select id="age"><option value="">Любой возраст</option>{''.join(f'<option value="{n}">{n} лет</option>' for n in range(2,19))}</select></div><div class="field"><label for="grade">Класс</label><select id="grade"><option value="">Любой класс</option>{''.join(f'<option value="{n}">{n} класс</option>' for n in range(1,12))}</select></div><div class="field"><label for="brand">Школа</label><select id="brand">{brandoptions}</select></div><fieldset><legend>Формат и первый шаг</legend><label class="check"><input type="checkbox" id="online">Онлайн</label><label class="check"><input type="checkbox" id="trial">Бесплатный первый урок</label><label class="check"><input type="checkbox" id="discount">Со скидкой</label></fieldset><div class="field"><label for="unit">Оплата</label><select id="unit"><option value="">Любая единица оплаты</option><option value="урок">За урок</option><option value="занятие">За занятие</option><option value="месяц">За месяц</option><option value="курс">За курс</option><option value="блок">За блок</option></select></div><div class="filter-help"><span>✳</span><h3>Понять свой интерес<br>можно с первого урока.</h3><p>Сравните формат и нагрузку. Уточните условия у школы до записи.</p><button class="text-button" data-quiz>Найти направление →</button></div><button class="button dark mobile-apply">Показать курсы</button></aside>'''
FEATURED=['programmirovanie','angliyskiy','dizayn','ege','oge','shahmaty','podgotovka-k-shkole','logoped']
def category_page(l):
 isroot=not l['slug'];cs=[COURSES[id] for id in l['courseIds']]
 middle=''
 if isroot:
  rest=[s for s in CATS if s not in FEATURED]
  middle='<section class="directions"><div class="section-top"><h2>Что интересно вашему ребёнку?</h2><span>У каждого направления — свой мир</span></div>'+directions(FEATURED)+'<details class="more-directions"><summary>Все 38 направлений <span>↓</span></summary>'+directions(rest,True)+'</details></section>'
 elif l['slug'] in ['ege','oge']:
  children=[x for x in D['landings'] if x.get('parent')==l['slug']]
  middle='<section class="subnav-section"><div class="section-top"><h2>Какой предмет подтянем?</h2></div><div class="subject-links">'+''.join(f'<a href="{x["path"]}">{E(x.get("label",x["h1"]))}<span>{x["count"]} ↗</span></a>' for x in children)+'</div></section>'
 elif l['slug']=='programmirovanie':
  sub=['scratch','python','roblox','minecraft','unity','web-razrabotka','iskusstvennyy-intellekt','robototehnika']
  middle='<section class="subnav-section"><div class="section-top"><h2>С чего хочется начать?</h2></div><div class="subject-links">'+''.join(f'<a href="{purl(x)}">{E(CATS[x]["label"])}<span>{CATS[x]["count"]} ↗</span></a>' for x in sub)+'</div></section>'
 catalogtitle='Найдём тот самый курс<span class="coral">.</span>' if isroot else 'Курсы: '+E(l.get('label',l['h1']))
 seo=f'<section class="seo-note"><h2>{E(l["h1"])}</h2><p>{E(l["intro"])}</p><p>{E(l.get("guide","Проверьте возраст, формат занятий, длительность и полную стоимость на сайте школы перед записью."))}</p></section>'
 body=f'''<main id="main"><div class="wrap">{crumbs(l)}{hero(l)}<div class="value-line"><span>✓ {len(D['courses'])} программ · {len(D['brands'])} {num(len(D['brands']),('школа','школы','школ'))}</span><span>✓ Возраст и формат сразу в карточке</span><span>✓ Сравните условия до записи</span></div>{middle}<section id="catalog" class="catalog-section"><div class="section-top catalog-title"><h2>{catalogtitle}</h2><button class="text-button" data-quiz>Помогите с выбором ↗</button></div><div class="catalog-layout">{filters(l)}<div class="catalog-content"><div class="catalog-tools"><label class="search"><span>⌕</span><input type="search" id="search" placeholder="Курс, школа или увлечение" aria-label="Поиск курса"></label><button class="mobile-filter-button button light" id="filter-toggle" aria-expanded="false" aria-label="Открыть фильтры">☷ Фильтры</button></div><div class="results-heading"><p id="result-count" aria-live="polite">{len(cs)} {num(len(cs))}</p><label class="sort"><select id="sort" aria-label="Сортировка курсов"><option value="default">По умолчанию</option><option value="age">Сначала для младших</option><option value="name">По названию</option><option value="price-lesson">Дешевле за урок</option><option value="price-month">Дешевле за месяц</option><option value="price-course">Дешевле за курс</option></select></label></div><div id="active-filters"></div><div class="course-grid" id="course-grid">{''.join(card(c) for c in cs)}</div><div id="empty" hidden><span>⌕</span><h3>По этим условиям курсов нет</h3><p>Попробуйте другое название или уберите часть фильтров.</p><button class="button dark" id="empty-reset">Сбросить фильтры</button></div><button class="button load-more" id="load-more">Показать ещё курсы <span>↓</span></button><p class="catalog-caption">Цена за занятие и цена за месяц — разные условия оплаты. Полную стоимость и расписание подтвердит школа.</p></div></div></section><section class="help-banner"><div class="help-art">✳</div><div><span class="eyebrow">ВЫБИРАТЬ ЛЕГЧЕ ВМЕСТЕ</span><h2>У каждого ребёнка<br>своё «это моё!»</h2><p>Три вопроса помогут понять,<br>с какого направления начать.</p></div><button class="button dark" data-quiz>Найти направление <span>↗</span></button></section>{seo}</div></main>'''
 image=landing_visual(l)
 schema={'@context':'https://schema.org','@type':'CollectionPage','name':l['h1'],'description':l['description'],'url':l['canonical'],'mainEntity':{'@type':'ItemList','numberOfItems':len(cs),'itemListElement':[{'@type':'ListItem','position':i+1,'url':'https://pro-schools.ru'+c['path'],'name':c['fullTitle']} for i,c in enumerate(cs)]}}
 extra='<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('</','<\/')+'</script>'
 content=document(l['title'],l['description'],l['path'],body,image=image,extra=extra)
 save(l['path']+'index.html',content)
 # Production never writes the site homepage.
def cta(c):
 return f'<a class="button dark" href="{E(c["url"])}" target="_blank" rel="sponsored nofollow noopener">{"Попробовать бесплатно" if c["trial"] else "Перейти на сайт школы"}<span>↗</span></a>'
def course_page(c):
 category=CATS[c['primaryCategory']];b=B[category['slug']];image='/kursy/assets/course-covers/'+c['id']+'.svg';topics=c['topics'];price=c['price'];unknown=c['priceValue'] is None
 tags=[c['age'],c['format']]+([c['tools']] if c['tools'] else [])
 tagmarkup=''.join(f'<span>{E(t)}</span>' for t in tags)
 program=''.join(f'<div class="outcome"><span>{i+1:02d}</span><h3>{E(t)}</h3></div>' for i,t in enumerate(topics)) if topics else '<p>Подробный учебный план и примеры занятий размещены на сайте школы.</p>'
 related=[x for x in D['courses'] if x['id']!=c['id'] and c['primaryCategory'] in x['categories']][:3]
 facts=[('Школа',c['brand']),('Возраст / класс',c['age']),('Формат',c['format']),('Расписание и нагрузка','Уточняются у школы')]
 faq=[('Какая полная стоимость курса?',c['condition']+' Перед записью проверьте итоговую сумму, единицу оплаты и количество занятий в пакете.'),('Можно ли сначала попробовать?','В каталоге отмечен бесплатный первый урок. Доступное время и условия подтвердит школа.' if c['trial'] else 'Наличие пробного занятия и его условия уточняются у школы.'),('Что понадобится для занятий?','В программе указаны инструменты: '+c['tools']+'. Технические требования и установку программ уточните у школы.' if c['tools'] else 'Технические требования, материалы и стартовый уровень уточняются у школы.'),('Как записаться?',f'Перейдите на сайт {c["brand"]}, уточните доступные группы и тариф. Заявка, договор и оплата оформляются напрямую со школой.')]
 offer=f'<div class="real-offer"><strong>{E(c["offer"])}</strong><span>{E(c["offerCondition"])}</span></div>' if c['offer'] else ''
 body=f'''<main id="main" class="detail-main"><div class="wrap"><div class="breadcrumbs"><a href="/kursy/">Курсы для детей</a><span>/</span><a href="{category['path']}">{E(category['label'])}</a><span>/</span>{E(c['brand'])}</div><section class="detail-hero full-course-hero" style="--category-color:{b['color']}"><div class="detail-hero-copy"><a class="school-name" href="/kursy/shkoly/{c['brandSlug']}/"><span class="school-mark">{E(c['brand'][0])}</span>{E(c['brand'])}</a><div class="eyebrow">{E(category['label'])}</div><h1>{E(c['fullTitle'])}</h1><p>{E(' · '.join(topics[:2]) or category['intro'])}</p><div class="detail-tags">{tagmarkup}</div></div><div class="detail-art course-art"><img src="{image}" alt="{E(c['fullTitle'])}" width="800" height="480" fetchpriority="high"><span class="project-sticker">С интереса начинается<br><strong>что-то большое.</strong></span></div></section><div class="detail-facts">{''.join(f'<div><span>{E(k.upper())}</span><strong>{E(v)}</strong></div>' for k,v in facts)}</div><nav class="detail-nav" aria-label="О курсе"><a href="#about">О программе</a><a href="#program">Темы курса</a><a href="#conditions">Условия</a><a href="#school">О школе</a><a href="#faq">Вопросы</a></nav><div class="detail-layout"><div class="detail-copy"><section id="about"><div class="eyebrow coral" style="margin-bottom:14px">ПОСМОТРИМ, ЧТО ВНУТРИ</div><h2>Знакомимся с программой</h2><p>{E(c['about'])}</p></section><section id="program"><h2>Чем будет заниматься ребёнок</h2><p class="program-intro">Темы из действующего каталога. Полный план, последовательность и количество занятий — на сайте школы.</p><div class="outcomes-grid">{program}</div><a class="text-button program-link" href="{E(c['url'])}" target="_blank" rel="sponsored nofollow noopener">Посмотреть полную программу ↗</a></section><section id="conditions"><h2>Выбрать спокойно,<br>зная условия</h2><p>{E(c['condition'])}</p>{offer}<div class="learning-strip"><div><b>01</b><h3>Познакомиться</h3><p>{'Начните с бесплатного первого урока.' if c['trial'] else 'Посмотрите программу на сайте школы.'}</p></div><div><b>02</b><h3>Обсудить формат</h3><p>Уточните размер группы, расписание и обратную связь.</p></div><div><b>03</b><h3>Выбрать курс</h3><p>Сверьте интерес ребёнка с нагрузкой и полной стоимостью.</p></div></div></section><section id="school"><h2>Кто будет учить</h2><div class="school-section"><div class="school-big-logo">{E(c['brand'][0])}</div><div><h3>{E(c['brand'])}</h3><p>Pro Schools помогает найти программу. Обучение, сопровождение, договор и оплата — на стороне школы.</p><a href="/kursy/shkoly/{c['brandSlug']}/">Все курсы {E(c['brand'])} ↗</a></div></div></section><section id="faq"><h2>Хорошие вопросы</h2>{''.join(f'<details class="module"><summary>{E(q)}</summary><p style="padding-left:0">{E(a)}</p></details>' for q,a in faq)}</section></div><aside aria-label="Стоимость и запись"><div class="price-panel"><div class="eyebrow"><span class="dot" style="background:#8a9d70"></span>{'ПЕРВЫЙ УРОК БЕСПЛАТНО' if c['trial'] else 'ВЫБЕРИТЕ СВОЙ ФОРМАТ'}</div><h2>{E(price)}</h2><p class="price-note">{E('Зависит от формата и пакета' if unknown else c['unit'])}</p>{cta(c)}<button class="save-detail" data-favorite="{c['id']}">♡ Сохранить, чтобы не потерять</button><ul><li>Договор напрямую со школой</li><li>Условия до записи</li><li>{E(c['age'])}</li></ul><p class="minor-note">{E(c['condition'])}</p><div class="panel-brand"><strong>{E(c['brand'])}</strong><a href="{E(c['url'])}" target="_blank" rel="sponsored nofollow noopener">Сайт школы ↗</a></div></div></aside></div><section class="detail-related"><div class="section-top"><h2>Ещё немного возможностей</h2><a href="{category['path']}">Все курсы направления ↗</a></div><div class="course-grid">{''.join(card(x) for x in related)}</div></section></div><div class="detail-mobile-action"><div><strong>{E(price)}</strong><small>{E('Уточняется у школы' if unknown else c['unit'])}</small></div>{cta(c)}</div></main>'''
 schema={'@context':'https://schema.org','@type':'Course','name':c['fullTitle'],'description':c['metaDescription'],'url':'https://pro-schools.ru'+c['path'],'provider':{'@type':'Organization','name':c['brand']},'inLanguage':'ru'}
 extra='<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('</','<\/')+'</script>'
 save(c['path']+'index.html',document(c['metaTitle'],c['metaDescription'],c['path'],body,'course',image,extra))
